1	import { redirect } from 'next/navigation'
2	import { cookies } from 'next/headers'
3	import { createClient } from '@/lib/supabase/server'
4	import { SidebarProvider } from '@/components/ui/sidebar'
5	import { AppSidebar } from '@/components/app/sidebar/AppSidebar'
6	import { AppHeader } from '@/components/app/sidebar/AppHeader'
7	import { PermissionsProvider } from '@/lib/team/permissions-context'
8	import { getUserPermissions } from '@/lib/team/permissions'
9	import { StudioParamSync } from '@/components/shared/StudioParamSync'
10	import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
11	import { getActiveLocation } from '@/lib/context/active-location'
12	
13	interface AppLayoutProps {
14	  children: React.ReactNode
15	}
16	
17	export default async function AppLayout({ children }: AppLayoutProps) {
18	  const supabase = await createClient()
19	  const {
20	    data: { user },
21	  } = await supabase.auth.getUser()
22	
23	  if (!user) {
24	    redirect('/login')
25	  }
26	
27	  // S15: resolve active studio via cookie (replaces .limit(1).single() pattern)
28	  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
29	  try {
30	    activeStudio = await getActiveStudio()
31	  } catch (err) {
32	    if (err instanceof NoStudioMembershipError) {
33	      redirect('/onboarding')
34	    }
35	    redirect('/onboarding')
36	  }
37	
38	  const { studioId, studio, role, plan, allMemberships } = activeStudio
39	
40	  // S15: resolve active location (depends on studioId — sequential, not Promise.all)
41	  const activeLocation = await getActiveLocation(studioId, role)
42	
43	  // Fetch user profile (parallel with nothing now that studio is resolved)
44	  const profileResult = await supabase
45	    .from('profiles')
46	    .select('full_name, avatar_url')
47	    .eq('id', user.id)
48	    .single()
49	
50	  // Permissions
51	  const permissionsSet =
52	    studioId && user ? await getUserPermissions(studioId, user.id) : new Set<string>()
53	  const permissionKeys = [...permissionsSet]
54	
55	  // Sidebar state from cookie
56	  const cookieStore = await cookies()
57	  const sidebarOpen = cookieStore.get('sidebar_state')?.value !== 'false'
58	
59	  const profile = profileResult.data
60	  const userName = profile?.full_name ?? user.email?.split('@')[0] ?? 'You'
61	  const userEmail = user.email ?? ''
62	  const userAvatarUrl = profile?.avatar_url ?? null
63	  const studioName = studio.name
64	  const studioLogoUrl = studio.logo_url ?? null
65	
66	  return (
67	    <PermissionsProvider permissionKeys={permissionKeys}>
68	      {/* S15: StudioParamSync handles ?studio=X deep links — renders null */}
69	      <StudioParamSync currentStudioId={studioId} />
70	      <SidebarProvider defaultOpen={sidebarOpen} className="h-svh">
71	        <AppSidebar
72	          locationCount={activeLocation.allLocations.length}
73	          plan={plan}
74	          studioName={studioName}
75	          studioLogoUrl={studioLogoUrl}
76	          role={role}
77	          permissionKeys={permissionKeys}
78	        />
79	        <AppHeader
80	          studioName={studioName}
81	          userName={userName}
82	          userEmail={userEmail}
83	          userAvatarUrl={userAvatarUrl}
84	          role={role}
85	          plan={plan}
86	          allMemberships={allMemberships}
87	          currentStudioId={studioId}
88	          currentLocationId={activeLocation.locationId}
89	          allLocations={activeLocation.allLocations}
90	          permissionKeys={permissionKeys}
91	        >
92	          {children}
93	        </AppHeader>
94	      </SidebarProvider>
95	    </PermissionsProvider>
96	  )
97	}
